const posOf = (kind: Kind): PartOfSpeech => {
  if (kind === 'der' || kind === 'die' || kind === 'das') return 'noun'
  if (kind === 'v') return 'verb'
  if (kind === 'a') return 'adj'
  return kind
}

export const B1_V2_VOCABULARY_11_20: VocabularyItem[] = UNITS.flatMap(({ id: unit, rows }) => {
  const items = rows.map(([kind, de, plural, ru, ky, example, exampleRu, exampleKy], index) => {
    const article = kind === 'der' || kind === 'die' || kind === 'das' ? kind : undefined
    return {
      id: `v${unit}-${index + 1}`,
      unit,
      pos: posOf(kind),
      article,
      de,
      plural: plural || undefined,
      ru,
      ky,
      example,
      exampleRu,
      exampleKy,
      related: [],
    }
  })
  return items.map((item, index) => ({
    ...item,
    related: [items[index - 1], items[index + 1], items[index + 2]]
      .filter((neighbor): neighbor is (typeof items)[number] => !!neighbor)
      .map(neighbor => neighbor.id),
  }))
})
